/* Optional lesson 11. Leaves existing stage data, submission services and required workflow intact. */
(()=>{'use strict';const api=window.CourseState,studio=window.CourseStudio,$=id=>document.getElementById(id);if(!api||!studio||$('stage11'))return;
const title='如何避免人像 AI 感（額外分享）';
const supplement='真實服飾電商棚拍，採用輕度商業修圖。皮膚保留自然細微膚色差異、適量毛孔與淡淡眼下紋理，臉部和身體的皮膚質感一致。頭髮具有自然的髮絲分組與少量碎髮。肩膀放鬆，重心合理，手指自然彎曲。衣物呈現符合實際材質的厚度、織紋、縫線與包邊，皺褶依照重力、身體姿勢與拉力形成。手指與腰頭確實接觸，接觸處有細小陰影及自然布料變形。左前方大型柔光箱照明，保留柔和明暗層次，人物與背景的光向一致。色彩中性，清晰度自然，皮膚與衣物均在景深範圍內。';
const physical='手指輕捏短褲腰頭，指尖與布料確實接觸，腰頭在捏握處輕微向外拉開，細小皺褶朝受力點聚集，指尖下方保留柔和接觸陰影，手腕與手指姿勢自然。';
const rows=[['皮膚過度光滑，像塑膠','自然細微膚色差異、適量毛孔、淡淡眼下紋理、輕度商業修圖'],['頭髮像整片貼上去','髮絲粗細與分組自然，少量碎髮，髮際線不過度整齊'],['表情與姿勢僵硬','肩膀放鬆；站姿時重心合理落在一隻腳，手指輕鬆彎曲'],['衣服像畫在身上','真實布料厚度、縫線與包邊，皺褶隨姿勢和拉力產生'],['人物像背景上的貼紙','光向一致，保留腋下、衣物邊緣及接觸處的柔和陰影']];
const fields={portraitUse:'使用情境',portraitProduct:'商品與人物',portraitContact:'動作與接觸關係',portraitBasePrompt:'原本的完整提示詞',portraitKeep:'這次要保留的設定'};
const section=document.createElement('section');section.id='stage11';section.className='portrait-lesson';section.hidden=true;
section.innerHTML='<span class="pill">額外分享｜可依需要選用</span><h2>11 '+title+'</h2><p class="lead">把「超寫實」改成看得見的細節，讓人物、服裝與商品的關係更自然。</p><section class="portrait-block"><h3>1. 提示詞寫出可觀察的細節</h3><div class="portrait-table"><table><thead><tr><th>容易出現 AI 感的地方</th><th>建議加入的描述</th></tr></thead><tbody>'+rows.map(([a,b])=>'<tr><td>'+a+'</td><td>'+b+'</td></tr>').join('')+'</tbody></table></div><p class="portrait-note"><strong>不必刻意加入大量瑕疵或顆粒。</strong>電商照片可以乾淨精緻，但皮膚與布料仍需要各自的質感。姿勢應配合原本的動作，坐姿不需要為了重心描述而改成站姿。</p></section><section class="portrait-block"><h3>2. 補上人物與物件的物理關係</h3><p>不要只寫「一隻手拉著腰頭」。請交代：<strong>碰到哪裡 → 力量往哪裡 → 物件如何變形 → 接觸處有什麼陰影。</strong></p><div class="portrait-examples"><article><h4>服飾範例｜手指捏住腰頭</h4><blockquote id="portraitPhysical"></blockquote><button type="button" data-portrait-copy="contact">複製服飾接觸描述</button></article><article><h4>運動用品範例｜手掌承托瑜珈磚</h4><p>手掌自然承托瑜珈磚底面，手指沿側邊輕鬆彎曲，掌面與商品確實接觸。接觸處保留柔和陰影，商品不穿過手指，手腕角度與商品重量的呈現合理，保留參考商品的外型、材質與配色。</p><p class="portrait-small">換成自己的產品時，依實際用途描述拿取或接觸，不補造用法、承重或性能。</p></article></div><p>這類描述比反覆加入「超寫實、8K、極致細節」更有針對性。鏡頭與光圈是視覺引導，不能保證成像符合真實攝影。</p></section><section class="portrait-block"><h3>3. 直接複製補充描述</h3><p>服飾電商範例：把這段接在原本的人像、服裝與構圖描述後。使用其他產品時，可用下方選填練習替換動作與接觸關係。</p><label for="portraitSupplement">降低 AI 感的補充描述<textarea id="portraitSupplement" rows="9" readonly></textarea></label><div class="actions"><button class="primary" type="button" data-portrait-copy="supplement">複製補充描述</button></div></section><section class="portrait-block"><h3>4. 換成我的產品與情境（選填）</h3><p>不用每格都填。已有畫面設定可沿用，只補這次要調整的地方。</p><label for="portraitUse">使用情境<select id="portraitUse"><option value="">沿用原本情境</option><option>服飾電商棚拍</option><option>運動用品使用情境</option><option>人物與產品介紹</option><option>其他商品或服務情境</option></select></label><label for="portraitProduct">商品與人物<input id="portraitProduct" maxlength="3000" placeholder="例如：女性自然拿取軟式壺鈴；也可留白沿用"></label><label for="portraitContact">動作與接觸關係<textarea id="portraitContact" rows="3" maxlength="20000" placeholder="誰的哪個部位，碰到商品哪裡？如何受力、變形或留下陰影？"></textarea></label><label for="portraitKeep">這次要保留的設定<input id="portraitKeep" maxlength="5000" placeholder="例如：人物身分、服裝、商品原色、構圖與核定文案"></label><label for="portraitBasePrompt">原本的完整提示詞<textarea id="portraitBasePrompt" rows="5" maxlength="300000" placeholder="可貼上原本的提示詞，或按下方按鈕帶入目前圖像練習。"></textarea></label><button type="button" id="portraitCarry">帶入目前圖像提示詞</button><h4>完整圖像生成指令</h4><p class="portrait-small">這份指令會要求 AI 直接生成圖片。若要調整既有圖像，請在 AI 工具附上原圖；參考照片不會由本網站自動上傳。</p><label for="portraitFullPrompt">我的完整指令<textarea id="portraitFullPrompt" rows="12" readonly></textarea></label><div class="actions"><button class="primary" type="button" data-portrait-copy="full">複製完整生成指令</button><button type="button" id="portraitDownload">下載 TXT</button></div></section><section class="portrait-block"><h3>生成後，先核對這四件事</h3><ul><li>臉部與身體的膚質、頭髮和手部細節是否一致？</li><li>手指是否真的碰到商品，皺褶與陰影是否符合受力？</li><li>人物、衣物、商品與背景的光向是否一致？</li><li>商品外型、材質、配色與標示是否仍符合參考資料？</li></ul><p class="portrait-small">提示詞能引導畫面，但不保證消除所有生成瑕疵；發布前仍需核對圖像。</p></section><p id="portraitStatus" role="status" aria-live="polite"></p>';
$('exercise').append(section);$('portraitPhysical').textContent=physical;$('portraitSupplement').value=supplement;
const nav=document.createElement('button');nav.className='step';nav.dataset.stage='11';nav.id='portraitNav';nav.innerHTML='<span>11 '+title+'</span><small>膚質、髮絲、布料、接觸與陰影</small>';document.querySelector('aside').insertBefore(nav,$('openResults'));
function full(v=api.get()){const base=v.portraitBasePrompt?.trim()||'',use=v.portraitUse||'沿用原本的人像商品情境',product=v.portraitProduct?.trim()||v.lessonPerson||v.topic||'沿用已確認的人物與商品',contact=v.portraitContact?.trim()||'沿用原本合理的動作；有接觸物件時，交代接觸位置、受力方向、合理變形與柔和接觸陰影。不要為了展示紋理改變姿勢或產品結構。';
return ['請依已確認的人物、產品、服裝與構圖，直接生成一張自然的人像商品圖；若我附上現有圖像，請以該圖為依據調整。','【本次情境】\n'+use+'\n商品與人物：'+product,base?'【原提示詞，作為畫面設定參考】\n'+base:'沿用原對話已確認的構圖、光線、尺寸與圖內文案；未提供的產品資料不要自行補造。','【質感調整】\n採用輕度商業修圖。皮膚保留自然細微膚色差異、適量毛孔與淡淡眼下紋理，臉部和身體的皮膚質感一致。髮絲分組自然，保留少量碎髮與不過度整齊的髮際線。表情自然，肩膀放鬆；承重與手指姿勢符合原本動作，不強迫坐姿或伸展動作改成站姿。\n衣物保留實際材質的厚度、織紋、縫線與包邊，皺褶依重力、姿勢和拉力形成；商品本身仍依參考材質呈現，不把所有產品都改成布料。','【動作與物理關係】\n'+contact,'【光線與清晰度】\n沿用原本光向；未指定時可用左前方大型柔光箱。人物與背景光向一致，保留腋下、衣物邊緣及物件接觸處的柔和陰影，明暗過渡自然。色彩中性，清晰度自然，重要的皮膚、衣物與商品細節清楚可見。','【保留與限制】\n'+(v.portraitKeep||'保留人物辨識、商品外型、原色、材質、圖紋、合理比例與核定文案。')+'\n不刻意加入大量瑕疵、顆粒或過度銳化；不補造功能、功效、規格或配件。','【執行方式】\n本輪依以上調整直接生成圖片；原提示詞中若有先規劃或等待確認的步驟，以本次直接生成的要求為準。需要維持原圖人物或商品時，請以我實際附上的參考圖為依據，不冒稱已讀取未提供的照片。'].filter(Boolean).join('\n\n');}
function header(){if(section.hidden)return;$('stageLabel').textContent='額外分享';$('where').textContent='目前所在：11 '+title;$('progress').textContent='選填練習，不影響原本作業流程';}
function refresh(){const v=api.get();for(const k of Object.keys(fields))if($(k).value!==(v[k]||''))$(k).value=v[k]||'';$('portraitFullPrompt').value=full(v);header();}
function show(scroll=true){for(let n=1;n<=10;n++)$('stage'+n).hidden=true;$('resultsPanel').hidden=true;section.hidden=false;document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-current',String(b.dataset.stage==='11')));$('openResults').setAttribute('aria-current','false');history.replaceState(null,'','#stage11');refresh();if(scroll)$('exercise').scrollIntoView({behavior:'smooth',block:'start'});}
const previousShow=api.show;api.show=function(n,scroll=true){if(Number(n)===11){show(scroll);return;}section.hidden=true;nav.setAttribute('aria-current','false');previousShow(n,scroll);};nav.onclick=()=>show();
const observer=new MutationObserver(()=>{if(!section.hidden&&([...Array(10)].some((_,i)=>!$('stage'+(i+1)).hidden)||!$('resultsPanel').hidden)){section.hidden=true;nav.setAttribute('aria-current','false');}});for(let n=1;n<=10;n++)observer.observe($('stage'+n),{attributes:true,attributeFilter:['hidden']});observer.observe($('resultsPanel'),{attributes:true,attributeFilter:['hidden']});
const oldRefresh=studio.refresh,oldLabels=studio.labels,oldExport=studio.exportPrompts;studio.refresh=function(v){oldRefresh(v);refresh();};studio.labels=()=>({...oldLabels(),...Object.fromEntries(Object.entries(fields).map(([k,t])=>[k,'11 額外分享｜'+t]))});studio.exportPrompts=v=>{const out=oldExport(v);if(Object.keys(fields).some(k=>v[k]?.trim()))out.push({stage:'11 額外分享｜降低人像 AI 感',text:full(v)});return out;};
section.addEventListener('input',e=>{if(Object.hasOwn(fields,e.target.id))api.set(e.target.id,e.target.value);});section.addEventListener('change',e=>{if(e.target.id==='portraitUse')api.set(e.target.id,e.target.value);});
section.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const key=b.dataset.portraitCopy;if(key){const text=key==='full'?full():key==='contact'?physical:supplement;try{await navigator.clipboard.writeText(text);$('portraitStatus').textContent='已複製。請貼到原本的 AI 對話，並視需要附上參考圖。';}catch{$('portraitStatus').textContent='瀏覽器未允許複製，請選取文字手動複製，或下載 TXT。';}}if(b.id==='portraitCarry'){const p=$('cs-prompt-image')?.value||'';if(p){api.set('portraitBasePrompt',p);$('portraitStatus').textContent='已帶入目前圖像練習的提示詞，請核對並補充本次動作。';}}if(b.id==='portraitDownload')api.download('降低人像AI感_完整提示詞.txt',full(),'text/plain;charset=utf-8');});
const css=document.createElement('style');css.textContent='.portrait-lesson{overflow-wrap:anywhere}.portrait-block{margin:22px 0;padding:22px;border:1px solid #ded8f1;border-radius:16px;background:#fff}.portrait-block h3{margin:0 0 16px}.portrait-block label{display:block;font-weight:600;margin:16px 0}.portrait-block input,.portrait-block select,.portrait-block textarea{display:block;box-sizing:border-box;width:100%;max-width:100%;padding:12px;margin-top:8px;border:1px solid #d3cbed;border-radius:10px;color:#333366;background:white;font:inherit;line-height:1.7}.portrait-block textarea[readonly]{background:#faf9fe}.portrait-table{overflow-x:auto}.portrait-table table{width:100%;border-collapse:collapse;min-width:450px}.portrait-table th,.portrait-table td{padding:14px;border-bottom:1px solid #e3def0;text-align:left;vertical-align:top;line-height:1.8}.portrait-table th{background:#f2efff}.portrait-note{padding:16px;background:#f7f5ff;border-radius:10px}.portrait-examples{display:grid;grid-template-columns:1fr 1fr;gap:16px}.portrait-examples article{padding:18px;border-radius:12px;background:#f7f5ff}.portrait-examples h4{margin-top:0}.portrait-examples blockquote{margin:0 0 16px;line-height:1.9}.portrait-small{font-size:14px;line-height:1.8}.portrait-lesson button{min-height:44px}#portraitStatus{color:#5742ae}@media(max-width:650px){.portrait-examples{grid-template-columns:1fr}.portrait-block{padding:16px}.portrait-block input,.portrait-block textarea,.portrait-block select{font-size:16px}}';document.head.append(css);
refresh();if(window.__coursePortraitRequested)show(false);window.addEventListener('hashchange',()=>{if(location.hash==='#stage11')show(false);else if(!section.hidden){const match=location.hash.match(/^#stage(\d+)$/);api.show(location.hash==='#results'?'results':match?Number(match[1]):1,false);}});window.CoursePortrait={full,supplement,physical,show};document.documentElement.dataset.coursePortrait='20261120';
})();

